from pathlib import Path
import json, html, re

p=Path(__file__).parent
out=p.parent
data=json.loads((p/'data.json').read_text())
parts=[]
def recipe(key, files):
    links=' · '.join(f'<a href="evidence/{f}">{f}</a>' for f in files)
    return f'<p class="source">Source: {links}</p><details><summary>Extracted settings / implementation notes</summary><pre>{html.escape(json.dumps(data[key],indent=2))}</pre></details>'
def channel(key,label):
    return f'<label><input type="checkbox" data-channel="{key}" checked> {label}</label>'
def lab(id,title,description,stage,duration,channels='',extra=''):
    return f'''<div class="lab" data-lab="{id}" data-duration="{duration}">
    <div class="lab-heading"><span class="eyebrow">Interactive study / {id}</span><h3>{title}</h3><p>{description}</p></div>
    <div class="stage {id}-stage">{stage}</div>{extra}
    <div class="controls"><button data-play>Replay sequence</button><button data-pause disabled>Pause</button><button data-start>Start state</button><button data-end>End state</button></div>
    <div class="channels">{channels}</div>
    <div class="timeline"><label for="time-{id}">Time</label><input id="time-{id}" data-time type="range" min="0" max="{duration}" value="{duration}" step="1"><output data-clock></output></div>
    <p class="readout" data-readout></p><p class="status" data-status>Ready. Replay, scrub, or use the study controls.</p></div>'''
def section(id,title,body):
    parts.append((id,title,f'<section id="{id}" class="chapter"><span class="eyebrow">Study {len(parts):02}</span><h2>{title}</h2>{body}</section>'))
def table(rows):
    return '<div class="table-wrap"><table><thead><tr><th>Where</th><th>Motion</th><th>What actually drives it</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+cell+'</td>' for cell in row)+'</tr>' for row in rows)+'</tbody></table></div>'

section('overview','A small vocabulary, used everywhere.', '''<p>Instrument’s homepage relies on repetition and restraint: one shared reveal system, a measured navigation pill, timed rotations, and media. The large visual changes inside the opening reel are video edits; they are not individual webpage animation timelines.</p><p><strong>The implementation is Nuxt/Vue + GSAP + anime.js + Swiper + CSS + Vimeo.</strong> GSAP handles split-text entrances, batch reveals, work filtering and page-load choreography. Anime.js handles the moving navigation bead and mobile menu. CSS supplies hover states, announcement transitions and logo swaps. Swiper supplies the service slideshow.</p><div class="numbers"><div><b>14</b><span>Interactive studies, grouped for learning. Not a count of every instance.</span></div><div><b>20px</b><span>The shared rise distance for split text and batches.</span></div><div><b>50ms</b><span>The recurring stagger that ties the reveal system together.</span></div></div>'''+table([
('Header / wordmark','SVG-path intro, direction-sensitive header, measured pill, announcements','GSAP, anime.js, CSS and a CMS timer'),
('Hero','Ambient loop, viewport playback, poster-to-reel fade','Vimeo media plus a 330ms CSS transition'),
('Intro / text touts','Word reveal followed by the CTA','SplitText + GSAP + a one-shot observer'),
('Recent work','Whole-section fade, category fade-out/in, media zoom-out, sibling dim','GSAP + active-grid state + CSS'),
('Clients / recognition','Whole-section fade, column-wise random logo rotation','Observer + 2500ms timers + CSS'),
('Services','Batch entrance of two columns, six-slide crossfade and progress bars','ScrollTrigger batch + Swiper + CSS'),
('Purpose','Parent fade and three independently triggered character reveals','Four observers; title opacity remains 0.3'),
('News / footer','Batch cards, word entrances, hover feedback; footer content itself stays still','Shared reveal helper + CSS')
])+'''<p class="small">Audited 7 October 2026 at desktop widths 1280/1440px and a 390px narrow viewport. Source facts, live observations and study reconstructions are distinguished. A narrow fine-pointer browser is not a touch-device test.</p>''')

logo=(p/'logo.svg').read_text()
logo=re.sub(r' style="[^"]*"','',logo)
introstage='<div class="intro-shell"><div class="intro-nav" data-intro-nav><span>WORK</span><span>SERVICES</span><span>ABOUT</span></div><div class="intro-logo">'+logo+'</div><div class="intro-preview">A site waits behind the scrim.</div><div class="intro-scrim"></div></div>'
section('entrance','Reveal the mark before the page.', '''<p>On the first large-logo load, ten SVG paths fade in over 800ms, starting at 500ms with a 40ms path stagger. Navigation starts at 800ms and takes 400ms. The page scrim is appended after the preceding timeline, then fades away over 400ms. All use <code>Power1.easeOut</code>, a quadratic ease.</p><p>Subsequent large-logo runs use a 400ms simultaneous path fade. Small-logo pages use another branch. Reduced motion sets the tween durations to zero, but explicit timeline positions remain; “zero duration” does not automatically remove every delay.</p>'''+lab('entrance','Wordmark and scrim','Original SVG paths. The surrounding shell is a reconstruction of the first large-logo branch.',introstage,2060,channel('paths','SVG path stagger')+channel('scrim','Page scrim'))+recipe('entrance',['usePageLoad.b2989f0a.js','default.5e393356.js','GlobalHeader.85b5dafa.css']))

revealstage='<div class="reveal-sample" data-reveal-copy></div><button class="sample-pill" data-reveal-cta>Explore the study →</button><svg class="curve-chart" viewBox="0 0 240 100" role="img" aria-label="Source expo-out ease curve"><path class="curve-guide" d="M10 90H230 M10 90V10"/><path data-curve-path fill="none" stroke="currentColor" stroke-width="2"/></svg>'
section('reveal','One trigger. Several granularities.', '''<p>The shared helper uses an IntersectionObserver with <code>rootMargin:0px 0px -15% 0px</code> and threshold 0. The lower 15% of the viewport does not count. On entry it starts an animation and unobserves that target, so ordinary reveals run once.</p><p>A plain fade takes 500ms with quadratic easing. Split words, characters and lines each take 1000ms with <code>expo.out</code>; opacity goes 0→1 and y goes 20→0px, with a 50ms stagger. Text touts append the CTA as another target after their words. The observer starts a time-based tween; the animation is not scrubbed by scroll distance.</p><p>The delivered GSAP 3.13 exponential curve includes endpoint correction. This study uses that actual equation, rather than substituting a vaguely similar CSS ease.</p>'''+lab('reveal','Split-text reveal','Substitute copy and fonts; exact rise, stagger, duration and delivered easing equation. Use the mode selector to compare granularity.',revealstage,2400,channel('opacity','Opacity')+channel('rise','20px rise')+channel('stagger','50ms stagger'),'<div class="controls"><label>Reveal mode <select data-reveal-mode><option value="words">Words + CTA</option><option value="chars">Characters</option><option value="lines">Lines</option><option value="fade">Whole-element fade</option></select></label></div>')+recipe('reveals',['useReveal.d63c7b47.js','TextTout.d1854d28.js','index.cf87e9ff.js']))

purposestage='<div class="purpose-sample"><p class="purpose-note">The section can fade in while the large type remains deliberately quiet.</p><div data-purpose-line="0" class="purpose-line serif">Shape</div><div data-purpose-line="1" class="purpose-line">A better</div><div data-purpose-line="2" class="purpose-line serif italic">Future.</div></div>'
section('purpose','Three lines. Four separate triggers.', '''<p>The purpose section gets one plain parent fade. Each of its three display lines has its own character reveal observer. Their trigger times follow their geometry and scrolling; there is no fixed “line 2 starts 400ms later” rule in the source.</p><p>Each character rises 20px over 1000ms with 50ms spacing. The title containers themselves stay at <strong>opacity 0.3</strong>. A fully revealed character has opacity 1 inside a 0.3 parent, so the finished type is intentionally pale. The serif, sans and italic mix is typography, not a font-morph animation.</p>'''+lab('purpose','Parent fade + character cascades','Source motion values. The combined replay uses illustrative trigger offsets of 0/500/1000ms; these are study choices, not extracted line delays. Trigger individual lines to feel the distinction.',purposestage,2400,channel('parent','Parent fade')+channel('chars','Character motion')+channel('stagger','Character stagger'),'<div class="controls"><button data-line-trigger="0">Trigger Shape</button><button data-line-trigger="1">Trigger A better</button><button data-line-trigger="2">Trigger Future</button><label><input type="checkbox" data-full-ink>Compare full-opacity type</label></div>')+recipe('purpose',['Purpose.82d88ce3.js','Purpose.de9fa175.css','useReveal.d63c7b47.js']))

cards=''.join(f'<div class="sample-card"><div class="sample-art art-{i}"><span>{i+1:02}</span></div><b>Study card {i+1}</b></div>' for i in range(4))
section('batch','Batch arrivals, then release the styles.', '''<p>The news grid and two service columns use the grid variant. It initially hides children and places them 20px down. Once the outer observer fires, ScrollTrigger batches individual children, collecting arrivals over a 200ms window with a default maximum of four. Each batch gets a 1000ms exponential entrance and a 50ms stagger.</p><p>When a batch finishes, source code clears its inline animation properties with <code>clearProps:"all"</code>. That lets CSS take over for later hovering and layout. Recent work explicitly passes <code>noReveal</code> to its nested grids; it fades the whole section instead of using this card-batch entrance.</p>'''+lab('batch','Card batch entrance','Simplified cards. Replay assumes four simultaneous arrivals. The two-batch mode illustrates separate collected groups; it is not a recorded scroll trace.','<div class="sample-grid">'+cards+'</div>',1500,channel('opacity','Opacity')+channel('rise','Rise')+channel('stagger','Stagger'),'<div class="controls"><label>Arrival grouping <select data-batch-mode><option value="4">One batch of four</option><option value="2">Two batches of two</option></select></label></div>')+recipe('reveals',['useReveal.d63c7b47.js','CardGrid.f95880ec.js','Diptych.2aaec1a5.js','FeaturedWorkGrid.51ecffa9.js']))

filterstage='<div class="filter-stage-grid"><div class="sample-grid filter-old">'+cards+'</div><div class="sample-grid filter-new">'+cards.replace('Study card','New project')+'</div></div>'
section('filters','Fade out, switch state, fade in.', '''<p>Choosing a work category first fades the old cards out over 500ms each, spaced by 50ms. The active category changes after that batch completes. The new cards then fade in with the same duration, stagger and exponential easing. For four old and four new cards, the nominal sequence totals 1300ms.</p><p>This is a sequence of opacity tweens around discrete state replacement. It is not a shared-layout or FLIP reflow. The category pill can be under the pointer before the selected category has changed; the selected state belongs to the completed switch.</p>'''+lab('filters','Category replacement','Two substitute card sets. The shared clock exposes the outgoing/incoming boundary; the source uses a GSAP timeline.',filterstage,1300,channel('stagger','50ms card stagger'),'<div class="controls"><label>New category <select data-filter-category><option>Brand</option><option>Marketing</option><option>Product</option></select></label></div>')+recipe('filters',['FeaturedWorkGrid.51ecffa9.js','FeaturedWorkGrid.28c5457d.css']))

beadstage='<div class="bead-nav"><div class="study-bead"></div><button data-bead-item="0">Work</button><button data-bead-item="1">Services</button><button data-bead-item="2">About</button></div>'
section('bead','Measure the target. Move one pill.', '''<p>The “abacus” is a single absolute bead. The helper measures the target’s inner shape against the container, subtracts 1px from x/y, and adds 2px to width/height. Movement and resizing take 300ms with <code>easeOutQuad</code>. Text colors take a separate 300ms linear CSS transition.</p><p>When the bead was invisible, source places it at the new geometry immediately and only fades it in, linearly over 300ms. Interruptions cancel the old animation before a replacement begins. This avoids a pile of queued moves while the pointer crosses links.</p>'''+lab('bead','Measured navigation bead','Actual DOM measurement in this study. Pointer and keyboard focus both move the pill; click retains a selection. The focus equivalent is a study improvement.',beadstage,300,'','<div class="controls"><label>Replay event <select data-bead-mode><option value="move">Move + resize</option><option value="appear">Appear at target</option><option value="hide">Disappear</option></select></label></div>')+recipe('abacus',['useAbacus.4568542c.js','entry.ee029dff.css']))

dropdownstage='<div class="dropdown-study"><button class="sample-pill" data-dropdown-trigger>Services ▾</button><div class="dropdown-items"><span>Brand</span><span>Marketing</span><span>Product</span></div></div>'
section('dropdown','A small overshoot, from the top edge.', '''<p>The desktop Services dropdown opens on hover or <code>focus-within</code>. Each item uses a 300ms CSS keyframe, delayed 60/120/180ms for the three current links. Scale goes 0→1.07 at 80%→1; opacity goes 0→1. Transform origin is top center.</p><p>Keyboard focus was verified on the live page, including those computed delays. Leaving hides the list with <code>display:none</code>; no corresponding animated exit was found. The study includes a close button so the abrupt exit is inspectable.</p>'''+lab('dropdown','Staggered dropdown','Source keyframe stops, easing and delays. Hover, focus, or click Services; use Close list for the discrete exit.',dropdownstage,480,channel('scale','Scale overshoot')+channel('stagger','60ms stagger'),'<div class="controls"><button data-dropdown-close>Close list</button></div>')+recipe('dropdown',['GlobalHeader.85b5dafa.css','GlobalHeader.28be4516.js']))

headerstage='<div class="header-scroll" tabindex="0" aria-label="Scroll this region to test header direction"><div class="mini-header"><span class="header-brand">INSTRUMENT</span><span class="header-announcement">A rotating announcement</span><span class="header-links">WORK / SERVICES</span></div><div class="scroll-content"><b>Scroll down, then up.</b><p>The header waits until you pass its height before hiding.</p><div>Keep scrolling</div><div>Reverse by more than 15px</div><div>Back toward the top</div></div></div>'
section('header','Direction changes the navigation state.', '''<p>The header is sticky, then gets translated up by 100% over 200ms. Source hides it on a positive sampled scroll delta once you are past the header’s height, provided the menu is closed. A sampled upward delta less than −15px reveals it. Returning to the top also reveals it; moving the mouse into the top header region can temporarily recover it.</p><p>A separate intersection sentinel switches the large-header announcement to the small wordmark. The small mark uses 300ms linear opacity/transform transitions; the announcement moves out over 300ms. Theme/background color transitions take 350ms. The big wordmark remains part of page flow—it is not a continuously scaling scroll morph.</p>'''+lab('header','Scroll-responsive header','Scroll the focusable region, or replay an illustrative down/up path. CSS durations and the directional condition are preserved. The local threshold is its measured header height.',headerstage,3000,channel('hide','Direction-based hiding')+channel('brand','Brand / announcement switch'))+recipe('header',['GlobalHeader.28be4516.js','GlobalHeader.85b5dafa.css']))

announcementstage='<div class="announcement-window"><span data-announcement-old>A studio announcement</span><span data-announcement-new>A different update</span></div>'
section('announcement','A rotator, despite the “marquee” name.', '''<p>The header’s component is named marquee, but its text is replaced in place. Outgoing text fades and moves up 10px. Incoming text fades and moves up from 10px below. Both take 300ms with CSS <code>ease-in-out</code>, inside a clipped window.</p><p>The interval is a CMS field named <code>marquee_time</code>, not a hardcoded component constant. Its numerical value was not extracted, so this audit does not invent one. Hover stops the timer and leaving restarts it; touch toggles it. Current linked announcements also caused Nuxt payload-prefetch warnings during inspection.</p>'''+lab('announcement','Announcement replacement','Substitute text. Replay isolates one transition; hover/focus freezes the study clock. No made-up source rotation interval.',announcementstage,300,channel('rise','±10px movement'))+recipe('announcement',['GlobalHeader.28be4516.js','GlobalHeader.85b5dafa.css']))

logostage='<div class="logo-columns"></div>'
section('logos','Rotate within columns, not across a strip.', '''<p>Clients and recognition badges share the same rotator. Below 1024px it splits the list into three columns; at 1024px and above, six. Source assigns items by index modulo column count, then shuffles each column. Every 2500ms it removes the previous active class and activates the next item, offset by column number ×100ms.</p><p>The CSS transition takes 300ms with ease-in-out: opacity 0→1, y −20→0px and visibility. On departure the old item goes back to −20px too. Reduced motion changes the period to 4000ms and removes the translate, while the logos continue cycling.</p>'''+lab('logos','Staggered logo columns','Substitute wordmarks in a deterministic order for scrubbing. The original shuffles randomly. This replay shows two changes with the source offsets.',logostage,5900,channel('shift','20px shift')+channel('offset','100ms per-column offset'),'<div class="controls"><label>Columns <select data-logo-cols><option value="6">Six · desktop</option><option value="3">Three · narrow</option></select></label><label>Source policy <select data-logo-policy><option value="normal">2500ms + movement</option><option value="reduced">4000ms, no movement</option></select></label></div>')+recipe('rotators',['ClientList.aeb94832.js','ClientListRotator.d01184ac.js','ClientListRotator.10fddf66.css']))

slidestage='<div class="slides-study"><div class="slide-art slide-a"><span>01 / 06</span></div><div class="slide-art slide-b"><span>02 / 06</span></div><div class="slide-label">Substitute artwork / slide <span data-slide-number>1</span></div></div><div class="slide-pagination">'+''.join(f'<button data-slide="{i}" aria-label="Select study slide {i+1}"><span></span></button>' for i in range(6))+'</div>'
section('slideshow','A media fade and a progress clock.', '''<p>The services slideshow has six slides and Swiper’s fade effect with <code>crossFade:true</code>. Autoplay delay is 3000ms. The component provides no speed override; the delivered Swiper default is 300ms. Fade layers use opacity, while their compensating transforms put the slides on top of each other.</p><p>Pagination runs its own 3000ms linear width animation. Pause calls Swiper autoplay pause/resume and pauses the active CSS progress bar. Selecting a bullet chooses a slide directly. These are related clocks, not a single tween: Swiper normally waits for a transition before its next autoplay wait. No loop option is enabled.</p><p>A reduced-motion autoplay-start handler attempts to stop through a different reference path than the regular controls. Its runtime result under an OS preference was not verified. This study consistently stops automatic motion when its reduced-motion option is enabled.</p>'''+lab('slideshow','Crossfade + progress bars','Six study frames made from simple artwork. Replay shows a 3000ms wait then a 300ms crossfade. Pagination selection uses the same fade duration.',slidestage,3300,channel('fade','Media crossfade')+channel('progress','Progress bar'))+recipe('slideshow',['Slideshow.1f424fa3.js','SlideshowPagination.0fcf7a73.js','SlideshowPagination.dfbf3412.css','swiper-vue.6126da36.js']))

mobilestage='<div class="mobile-shell"><div class="mobile-art"><span>Content behind the menu</span></div><div class="mobile-overlay"><div class="mobile-menu-list">'+''.join(f'<div>{x}<i>↗</i></div>' for x in ['Home','Work','Services','About','Careers','Latest','Contact'])+'</div><div class="mobile-social"><span>Network A</span><span>Network B</span><span>Network C</span></div></div></div>'
section('mobile','Enter softly. Exit with acceleration.', '''<p>Opening first fades the overlay in over 250ms, linearly. Its background has a static 16px backdrop blur. When that fade completes, seven link rows enter over 1000ms with 100ms spacing, opacity 0→1 and y 15→0px, using <code>easeOutCubic</code>.</p><p>The social links start 800ms after the overlay completes. They rise from 100% of their height over 1000ms with <code>easeOutElastic</code>. Closing reverses the rhythm: link rows move to −75px over 400ms with ease-in cubic and the same 100ms stagger. Social links wait 500ms, then move −32px over 400ms. The overlay finally fades out over 250ms.</p><p>The source’s link completion callback schedules the overlay fade; nested submenu rows can affect the total. The study groups that final fade after seven top-level rows finish. Escape was verified live. The delivered menu tween handlers have no local reduced-motion guard.</p>'''+lab('mobile','Mobile menu sequence','Exact top-level entry values and source curves. Exit is a seven-row teaching reconstruction; submenu timings can overlap differently in the real DOM.',mobilestage,2050,channel('stagger','Link stagger')+channel('social','Elastic social entrance'),'<div class="controls"><label>Direction <select data-mobile-direction><option value="open">Open menu</option><option value="close">Close menu</option></select></label></div>')+recipe('mobileMenu',['GlobalHeader.28be4516.js','GlobalHeader.85b5dafa.css','useAbacus.4568542c.js']))

microstage='<div class="hover-grid">'+''.join(f'<button class="hover-card" aria-label="Emphasize study card {i+1}"><span class="hover-art art-{i}"><b>{i+1:02}</b></span><span>Study {i+1}</span></button>' for i in range(3))+'</div><button class="press-pill">Press and hold this pill →</button><div class="media-switch"><div class="ambient-study">AMBIENT / VIDEO CONTENT</div><div class="reel-study">MAIN REEL / SEPARATE IFRAME</div><div class="study-play-icon">▶</div></div>'
section('micro','A zoom-out, a dim, and a media switch.', '''<p>Work and news media rest at scale 1.05 and settle to scale 1 on hover over 250ms with the implicit CSS ease. The crop relaxes instead of punching toward you. In grids with fewer than five cards, hovering dims sibling containers to opacity 0.5 over 250ms.</p><p>Button shapes compress to scale 0.975 on press over 150ms ease-in-out. Their colors use separate 250ms transitions. These small effects complete the heavier reveals without creating another large entrance.</p><p>The hero’s ambient loop is a Vimeo video. An observer loads and plays visible media and pauses it offscreen; automatic play is gated by motion preference. Clicking the hero shows a separate main-reel iframe and fades away the poster and play icon over 330ms. True touch mode uses the square ambient variant and requests fullscreen; the fine-pointer browser uses landscape. Animation inside the video is authored media, not CSS.</p><p class="small">A 150ms .95→1 play-icon hover rule is delivered, but the icon has pointer-events:none and no parent-hover trigger was found. It is documented as an unverified active effect, not silently counted as working motion.</p>'''+lab('micro','Hover composition + media handoff','Hover or focus the cards. Press the pill. Replay isolates the 330ms poster-to-main-media handoff with substitute artwork; it does not emulate Vimeo playback.',microstage,330)+recipe('micro',['WorkCard.f3074127.css','LatestCard.0f4b9424.css','CardGrid.d1e380fa.css','entry.ee029dff.css'])+recipe('video',['VideoFeature.228d8805.js','VideoFeature.772accc9.css','VideoClip.979b033d.js']))

cookiestage='<div class="cookie-window"><div class="cookie-banner"><span>A small first-visit notice</span><b>Dismiss →</b></div></div><svg class="cookie-curve" viewBox="0 0 240 100" role="img" aria-label="Anticipation curve dips below zero before exiting"><path class="curve-guide" d="M10 60H230 M10 90V10"/><path data-cookie-curve fill="none" stroke="currentColor" stroke-width="2"/></svg>'
section('cookie','Anticipation in the small print.', '''<p>The first-visit cookie notice waits 250ms, then uses a 500ms translate transition between 100px and 0. Its cubic Bézier is <code>(.36,0,.66,-.56)</code>. The negative second y control makes the curve dip below zero: the banner briefly moves in the opposite direction before committing to its travel.</p><p>Dismissal reverses the endpoints with the same curve. This is a reversible local illustration of that timing, not a consent interface. No local reduced-motion guard was found in this transition CSS.</p>'''+lab('cookie','Anticipating banner','Source curve and offsets. The study frame clips the travel; entrance includes the 250ms first-show wait.',cookiestage,750,'','<div class="controls"><label>Direction <select data-cookie-direction><option value="enter">Enter notice</option><option value="leave">Dismiss notice</option></select></label></div>')+recipe('cookie',['GDPR.a3fa72c8.js','GDPR.7aa792be.css']))

section('build','Borrow the system, not just the durations.', '''<p><strong>The reusable idea is a shared motion vocabulary.</strong> Separate triggers from rendering, use one reveal helper, keep the stagger tiny, and let finished reveals release inline transforms. Pair one larger entrance with restrained hovering; avoid re-running every heading while the user scrolls backward.</p><p>CSS is sufficient for image scale, sibling dimming, press feedback, the dropdown keyframes, announcements, logo swapping and the consent notice. A timer or component state decides when several of those effects happen. “Rendered with CSS” does not mean “orchestrated entirely by CSS.”</p><p>GSAP’s splitting and batching make responsive text and viewport arrivals practical. Anime.js measures and moves the bead and sequences the menu. A React/Motion implementation could reproduce these measured interactions and presence changes, but it is not required for the simple CSS states. Media playback belongs to a separate player lifecycle.</p><div class="callout"><b>Reduced motion needs a policy, not just a slower number.</b><p>The delivered site skips reveal initialization, disables ambient autoplay, slows logo cycling to 4000ms and removes its vertical shift. Several other clocks and menu tweens have no equivalent local guard. The slideshow stop branch was not runtime-validated. This showcase starts with no autoplay, respects the OS preference, and shows destinations immediately when Reduced motion is on.</p></div><p>Most page tweens animate opacity and transforms, but there are important exceptions: the bead animates measured width/height, progress animates width, and the menu uses backdrop blur. Those can have different layout/paint costs. The observer pauses ambient video offscreen, while the logo timers and slideshow are not visibly gated by a viewport observer. No frame-time or compositor trace was recorded, so this is a mechanism audit, not an FPS certification.</p><p class="small">Generic 300ms route-fade CSS is shipped, but the inspected Nuxt default pageTransition is false. Splide spinner styles are also bundled without an active homepage Splide element. Neither is promoted into the verified animation inventory.</p>''')

section('evidence','Read the source. Compare the real page.', '''<p>The studies are offline teaching reconstructions. Timing, easing and event order follow the delivered source where stated. Only the entrance wordmark uses original artwork. Study typography, project artwork, wordmarks, video content and layout shells are substitutes. Purpose trigger offsets, batch arrival groups, the scroll replay and the grouped menu exit are explicitly illustrative.</p><p>The actual homepage was inspected for category replacement, hover media/sibling opacity, desktop focus-triggered dropdowns, mobile menu state/Escape, header recovery, slideshow pause/selection, split-text hidden states, pale purpose titles and the hero’s iframe handoff. The browser also emitted route-payload prefetch warnings for two announcement-linked articles; those are preserved as a limitation, not attributed to the teaching demos.</p><div class="source-links"><a href="https://www.instrument.com/" target="_blank" rel="noreferrer">Original homepage ↗</a><a href="homepage-motion-data.json">Extracted motion data</a><a href="evidence/asset-manifest.json">78 asset records / SHA-256 hashes</a><a href="evidence/matched-motion-rules.txt">Motion-rule index</a><a href="live-homepage.png">Full homepage capture</a></div><div class="evidence-grid"><figure><img src="live-purpose.png" alt="Instrument purpose typography in the actual wide desktop layout"><figcaption>Actual purpose layout: independent lines, 0.3 title opacity.</figcaption></figure><figure><img src="live-mobile-menu.png" alt="Instrument actual open mobile navigation"><figcaption>Actual mobile menu: static backdrop blur with sequential content.</figcaption></figure></div><p class="small">The full-page capture can cause observers to see an enlarged viewport; it is a layout record, not timing evidence. Trigger and timing conclusions come from the source and normal-viewport inspection. Public source files were read as text and preserved for reference, not imported into the showcase.</p>''')

nav=''.join(f'<a href="#{id}"><span>{i:02}</span>{title}</a>' for i,(id,title,body) in enumerate(parts))
